import React, { useEffect, useState } from 'react';
import axios from 'axios';

function App() {
  const [productos, setProductos] = useState([]);
  const [nuevoProducto, setNuevoProducto] = useState({
    nombre: '',
    categoria: '',
    precio: '',
    stockActual: ''
  });

  useEffect(() => {
    obtenerProductos();
  }, []);

  const obtenerProductos = async () => {
    try {
      const respuesta = await axios.get('http://localhost:8080/api/productos');
      setProductos(respuesta.data);
    } catch (error) {
      console.error("Error al obtener productos:", error);
    }
  };

  const manejarCambio = (e) => {
    setNuevoProducto({
      ...nuevoProducto,
      [e.target.name]: e.target.value
    });
  };

  const guardarProducto = async (e) => {
    e.preventDefault();
    try {
      await axios.post('http://localhost:8080/api/productos', nuevoProducto);
      alert("¡Producto registrado con éxito!");
      setNuevoProducto({ nombre: '', categoria: '', precio: '', stockActual: '' }); // Limpiar formulario
      obtenerProductos(); // Refrescar la tabla
    } catch (error) {
      console.error("Error al guardar:", error);
    }
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'Arial' }}>
      <h1>Gestión de Inventario - El Paisita UP</h1>

      {/* Formulario para registrar productos */}
      <div style={{ marginBottom: '30px', padding: '15px', border: '1px solid #ccc', borderRadius: '8px' }}>
        <h3>Registrar Nuevo Producto</h3>
        <form onSubmit={guardarProducto}>
          <input name="nombre" placeholder="Nombre (ej. Tinto)" value={nuevoProducto.nombre} onChange={manejarCambio} required style={{marginRight: '10px'}} />
          <input name="categoria" placeholder="Categoría (ej. Bebidas)" value={nuevoProducto.categoria} onChange={manejarCambio} required style={{marginRight: '10px'}} />
          <input name="precio" type="number" placeholder="Precio" value={nuevoProducto.precio} onChange={manejarCambio} required style={{marginRight: '10px'}} />
          <input name="stockActual" type="number" placeholder="Stock Inicial" value={nuevoProducto.stockActual} onChange={manejarCambio} required style={{marginRight: '10px'}} />
          <button type="submit" style={{backgroundColor: '#28a745', color: 'white', border: 'none', padding: '5px 15px', cursor: 'pointer'}}>Guardar</button>
        </form>
      </div>

      {/* Tabla de productos */}
      <table border="1" style={{ width: '100%', textAlign: 'left', borderCollapse: 'collapse' }}>
        <thead>
          <tr style={{ backgroundColor: '#f2f2f2' }}>
            <th>Nombre</th>
            <th>Categoría</th>
            <th>Precio</th>
            <th>Stock</th>
          </tr>
        </thead>
        <tbody>
          {productos.map((prod) => (
            <tr key={prod.id}>
              <td>{prod.nombre}</td>
              <td>{prod.categoria}</td>
              <td>${prod.precio}</td>
              <td>{prod.stockActual}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

export default App;
